-- JenLow Network · Cloudflare D1 / SQLite
-- 0001: identities, personal settings, skills and trusted relationships.
-- All IDs are app-generated opaque UUID/ULID strings, never integer user IDs.
-- Timestamps are UTC text generated by SQLite CURRENT_TIMESTAMP.
CREATE TABLE users (
 id TEXT PRIMARY KEY,
 handle TEXT NOT NULL COLLATE NOCASE UNIQUE,
 display_name TEXT NOT NULL,
 email TEXT NOT NULL COLLATE NOCASE UNIQUE,
 bio TEXT NOT NULL DEFAULT '',
 city TEXT,
 country_code TEXT,
 church_name TEXT,
 avatar_asset_key TEXT,
 account_status TEXT NOT NULL DEFAULT 'active' CHECK(account_status IN ('active','suspended','deactivated','deleting')),
 email_verified_at TEXT,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted_at TEXT
);
CREATE INDEX idx_users_city ON users(city) WHERE account_status='active';

CREATE TABLE auth_identities (
 id TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(provider IN ('email','google','apple','oidc')),
 provider_subject TEXT NOT NULL,
 linked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 last_sign_in_at TEXT,
 UNIQUE(provider,provider_subject)
);
CREATE INDEX idx_auth_user ON auth_identities(user_id);

CREATE TABLE user_preferences (
 user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 locale TEXT NOT NULL DEFAULT 'fr',
 timezone TEXT NOT NULL DEFAULT 'Europe/Paris',
 profile_visibility TEXT NOT NULL DEFAULT 'public' CHECK(profile_visibility IN ('public','members','private')),
 show_church INTEGER NOT NULL DEFAULT 0 CHECK(show_church IN (0,1)),
 discoverable INTEGER NOT NULL DEFAULT 1 CHECK(discoverable IN (0,1)),
 push_enabled INTEGER NOT NULL DEFAULT 0 CHECK(push_enabled IN (0,1)),
 prayer_reminders_enabled INTEGER NOT NULL DEFAULT 0 CHECK(prayer_reminders_enabled IN (0,1)),
 browsing_reminder_enabled INTEGER NOT NULL DEFAULT 1 CHECK(browsing_reminder_enabled IN (0,1)),
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE talents (
 id TEXT PRIMARY KEY,
 name TEXT NOT NULL COLLATE NOCASE UNIQUE,
 category TEXT NOT NULL DEFAULT 'other',
 is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1))
);
CREATE INDEX idx_talents_category ON talents(category);

CREATE TABLE user_talents (
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 talent_id TEXT NOT NULL REFERENCES talents(id) ON DELETE RESTRICT,
 level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 5),
 can_teach INTEGER NOT NULL DEFAULT 0 CHECK(can_teach IN (0,1)),
 wants_to_learn INTEGER NOT NULL DEFAULT 0 CHECK(wants_to_learn IN (0,1)),
 wants_tandem INTEGER NOT NULL DEFAULT 0 CHECK(wants_tandem IN (0,1)),
 available_for_projects INTEGER NOT NULL DEFAULT 0 CHECK(available_for_projects IN (0,1)),
 notes TEXT,
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(user_id,talent_id)
);
CREATE INDEX idx_user_talents_match ON user_talents(talent_id,available_for_projects,level);

-- Ordinary JenLow contacts and personal Circle are intentionally distinct.
-- Only a bilateral, accepted Circle relationship can authorize Circle-only features.
CREATE TABLE contact_requests (
 id TEXT PRIMARY KEY,
 requester_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','cancelled')),
 requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 responded_at TEXT,
 CHECK(requester_id <> recipient_id),
 UNIQUE(requester_id,recipient_id)
);
CREATE INDEX idx_contact_requests_inbox ON contact_requests(recipient_id,status);

CREATE TABLE contacts (
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 contact_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(user_id <> contact_user_id),
 PRIMARY KEY(user_id,contact_user_id)
);
CREATE INDEX idx_contacts_reverse ON contacts(contact_user_id);

CREATE TABLE circle_requests (
 id TEXT PRIMARY KEY,
 requester_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','revoked')),
 connection_label TEXT,
 requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 responded_at TEXT,
 CHECK(requester_id <> recipient_id),
 UNIQUE(requester_id,recipient_id)
);
CREATE INDEX idx_circle_requests_inbox ON circle_requests(recipient_id,status);

CREATE TABLE circle_members (
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 member_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 circle_request_id TEXT NOT NULL REFERENCES circle_requests(id) ON DELETE CASCADE,
 relationship_label TEXT,
 added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(user_id <> member_user_id),
 PRIMARY KEY(user_id,member_user_id)
);
CREATE INDEX idx_circle_members_reverse ON circle_members(member_user_id);
-- API must verify circle_request.status = accepted and reciprocal consent
-- before writing BOTH directed circle_members rows.

CREATE TABLE user_blocks (
 blocker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 blocked_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 reason TEXT,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 CHECK(blocker_id <> blocked_id),
 PRIMARY KEY(blocker_id,blocked_id)
);

CREATE TABLE consent_records (
 id TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 consent_type TEXT NOT NULL CHECK(consent_type IN ('terms','privacy','marketing','recording','external_share')),
 policy_version TEXT NOT NULL,
 granted INTEGER NOT NULL CHECK(granted IN (0,1)),
 recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 source TEXT,
 ip_hash TEXT
);
CREATE INDEX idx_consents_user_type ON consent_records(user_id,consent_type,recorded_at);

CREATE TABLE user_devices (
 id TEXT PRIMARY KEY,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 platform TEXT NOT NULL CHECK(platform IN ('ios','android','web')),
 push_token_ciphertext TEXT,
 push_token_hash TEXT UNIQUE,
 last_seen_at TEXT,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 revoked_at TEXT
);
CREATE INDEX idx_devices_user ON user_devices(user_id,revoked_at);
